package com.zerotrust.internalresource.audit; import com.zerotrust.internalresource.config.ResourceSecurityProperties; import jakarta.servlet.http.HttpServletRequest; import org.springframework.stereotype.Component; @Component public class GatewayAccessEvaluator { private final ResourceSecurityProperties properties; public GatewayAccessEvaluator(ResourceSecurityProperties p){properties=p;} public boolean isGatewayAccess(HttpServletRequest request){ return properties.getTrustedGatewayIps().contains(request.getRemoteAddr()) && properties.getGatewayHeaderValue().equals(request.getHeader(properties.getGatewayHeaderName())); } }